#!/usr/bin/env python3
"""Extract __inline_bsearch() from include/linux/bsearch.h.

bsearch()'s body is a static inline in a header, not in lib/bsearch.c, so
this is where the oracle has to come from. Extracted rather than copied, for
the same reason as everything else here.
"""
import re
import sys

src = open(sys.argv[1]).read()
m = re.search(r"(static __always_inline\s*\n?void \*__inline_bsearch.*?\n\})", src, re.S)
if not m:
    sys.exit("could not find __inline_bsearch in " + sys.argv[1])
open(sys.argv[2], "w").write(
    "/* GENERATED by extract_bsearch.py from include/linux/bsearch.h. */\n"
    + m.group(1) + "\n"
)
